        uint16_t num_events = (buffer[0] << 8) | buffer[1];
        printf("Received %u events\n", num_events);

        for (uint16_t i = 0; i < num_events; ++i) {
            if (2 * i + 1 >= BUFFER_SIZE) {
                printf("Packet too large\n");
                break;
