            // Big-endian unpacking (network byte order)
            uint16_t index = (buffer[2*i] << 8) | buffer[2*i+1];
            uint16_t value = (buffer[2*i+2] << 8) | buffer[2*i+3];

            if (index >= 0 && index < NUM_EVENTS) {
                libevdev_uinput_write_event(controller, REGISTERED_EVENTS[index].type,
                                            REGISTERED_EVENTS[index].code, value);
            }
        }

        // No response sent (equivalent to original server behavior)
    }

    close(sockfd);
}

